gNG(){return"\u0421\u043f\u0438\u0441\u043e\u043a \u2014 \u0432\u0430\u0448 \u043b\u0438\u0447\u043d\u044b\u0439 \u043a\u0430\u0442\u0430\u043b\u043e\u0433 \u0442\u043e\u0432\u0430\u0440\u043e\u0432, \u043e\u043d \u043d\u0438\u043a\u043e\u0433\u0434\u0430 \u043d\u0435 \u043e\u0447\u0438\u0449\u0430\u0435\u0442\u0441\u044f. \u041f\u0435\u0440\u0435\u0434 \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u043e\u043c \u043e\u0442\u043c\u0435\u0447\u0430\u0435\u0442\u0435, \u0447\u0442\u043e \u043d\u0443\u0436\u043d\u043e \u043a\u0443\u043f\u0438\u0442\u044c, \u2014 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u043e\u0435 \u0441\u043f\u043e\u043a\u043e\u0439\u043d\u043e \u0436\u0434\u0451\u0442 \u0441\u0432\u043e\u0435\u0433\u043e \u0447\u0430\u0441\u0430."},
